import { supabase } from './supabaseClient.js';

// Get UI elements (these will be assigned in app.js or when DOM is ready)
let signUpForm, loginForm, userStatus, authMessages, userEmailDisplay;
let signUpButton, loginButton, logoutButton;
let signUpEmailInput, signUpPasswordInput, loginEmailInput, loginPasswordInput;

// Function to initialize Auth UI elements (call this from app.js after DOM is loaded)
export function initAuthUI() {
    signUpForm = document.getElementById('signUpForm');
    loginForm = document.getElementById('loginForm');
    userStatus = document.getElementById('userStatus');
    authMessages = document.getElementById('authMessages');
    userEmailDisplay = document.getElementById('userEmail'); // Using userEmail as per instruction

    signUpButton = document.getElementById('signUpButton');
    loginButton = document.getElementById('loginButton');
    logoutButton = document.getElementById('logoutButton');

    signUpEmailInput = document.getElementById('signUpEmail');
    signUpPasswordInput = document.getElementById('signUpPassword');
    loginEmailInput = document.getElementById('loginEmail');
    loginPasswordInput = document.getElementById('loginPassword');

    // Attach event listeners
    if (signUpForm) {
        signUpForm.addEventListener('submit', async (event) => {
            event.preventDefault();
            await handleSignUp();
        });
    }
    if (loginForm) {
        loginForm.addEventListener('submit', async (event) => {
            event.preventDefault();
            await handleLogin();
        });
    }
    if (logoutButton) {
        logoutButton.addEventListener('click', async () => {
            await handleLogout();
        });
    }
}

export async function handleSignUp() {
    const email = signUpEmailInput.value;
    const password = signUpPasswordInput.value;
    authMessages.textContent = ''; // Clear previous messages

    const { data, error } = await supabase.auth.signUp({ email, password });

    if (error) {
        authMessages.textContent = `Sign-up error: ${error.message}`;
        console.error('Sign-up error:', error);
    } else {
        authMessages.textContent = 'Sign-up successful! Check your email for verification.';
        console.log('Sign-up successful:', data);
        // UI update will be handled by onAuthStateChange if email confirmation is not required,
        // or user will be in a pending state until confirmation.
    }
}

export async function handleLogin() {
    const email = loginEmailInput.value;
    const password = loginPasswordInput.value;
    authMessages.textContent = ''; // Clear previous messages

    const { data, error } = await supabase.auth.signInWithPassword({ email, password });

    if (error) {
        authMessages.textContent = `Login error: ${error.message}`;
        console.error('Login error:', error);
    } else {
        // User is logged in. UI update will be handled by onAuthStateChange.
        // authMessages.textContent = 'Login successful!'; // Message handled by onAuthStateChange
        console.log('Login successful:', data);
    }
}

export async function handleLogout() {
    authMessages.textContent = ''; // Clear previous messages
    const { error } = await supabase.auth.signOut();

    if (error) {
        authMessages.textContent = `Logout error: ${error.message}`;
        console.error('Logout error:', error);
    } else {
        // User is logged out. UI update will be handled by onAuthStateChange.
        // authMessages.textContent = 'Logged out successfully.'; // Message handled by onAuthStateChange
        console.log('Logout successful');
    }
}

function updateAuthUI(user) {
    if (user) {
        if (signUpForm) signUpForm.style.display = 'none';
        if (loginForm) loginForm.style.display = 'none';
        if (userStatus) userStatus.style.display = 'block';
        if (userEmailDisplay) userEmailDisplay.textContent = user.email;
        // Clear any previous auth messages that are not errors
        if (authMessages.textContent.includes('successful') || authMessages.textContent.includes('verification')) {
            // Keep error messages
        } else {
            authMessages.textContent = '';
        }

    } else {
        if (signUpForm) signUpForm.style.display = 'block';
        if (loginForm) loginForm.style.display = 'block';
        if (userStatus) userStatus.style.display = 'none';
        if (userEmailDisplay) userEmailDisplay.textContent = '';
    }
}

export async function checkUserSession() {
    const { data: { session } } = await supabase.auth.getSession();
    // The onAuthStateChange listener will fire if there's a session,
    // so we don't strictly need to call updateAuthUI here,
    // but it can be useful for an initial synchronous check if needed.
    // For now, rely on onAuthStateChange.
    if (session) {
        console.log('User session found:', session);
        // updateAuthUI(session.user); // Let onAuthStateChange handle this for consistency
    } else {
        console.log('No active user session.');
        updateAuthUI(null); // Ensure UI is in logged-out state if no session and no event fires immediately
    }
}

// Listen for authentication state changes
supabase.auth.onAuthStateChange((event, session) => {
    console.log('Auth event:', event, session);
    const user = session ? session.user : null;
    updateAuthUI(user);

    if (event === 'SIGNED_IN') {
        authMessages.textContent = 'Successfully logged in!';
    } else if (event === 'SIGNED_OUT') {
        authMessages.textContent = 'You have been logged out.';
        // Clear sensitive input fields on logout
        if(signUpEmailInput) signUpEmailInput.value = '';
        if(signUpPasswordInput) signUpPasswordInput.value = '';
        if(loginEmailInput) loginEmailInput.value = '';
        if(loginPasswordInput) loginPasswordInput.value = '';
    } else if (event === 'USER_UPDATED') {
        // Handle user updates if necessary
        authMessages.textContent = 'User profile updated.';
    } else if (event === 'PASSWORD_RECOVERY') {
        authMessages.textContent = 'Password recovery email sent.';
    } else if (event === 'TOKEN_REFRESHED') {
        console.log('Token refreshed');
    }
    // Clear message after a few seconds, unless it's an error that should persist
    if (authMessages.textContent && !authMessages.textContent.toLowerCase().includes('error')) {
        setTimeout(() => {
            authMessages.textContent = '';
        }, 5000);
    }
});

